CREATE TABLE IF NOT EXISTS staff(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,role TEXT DEFAULT 'Staff',username TEXT UNIQUE NOT NULL,pass_hash TEXT NOT NULL,salt TEXT NOT NULL,duty_start TEXT DEFAULT '10:00',duty_end TEXT DEFAULT '22:00',active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,staff_id INTEGER NOT NULL,punch_in INTEGER NOT NULL,punch_out INTEGER,late INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS breaks(id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,type TEXT NOT NULL,started INTEGER NOT NULL,ended INTEGER);
CREATE TABLE IF NOT EXISTS fines(id INTEGER PRIMARY KEY AUTOINCREMENT,staff_id INTEGER NOT NULL,staff_name TEXT,amount INTEGER NOT NULL,reason TEXT,at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,message TEXT NOT NULL,at INTEGER NOT NULL,seen INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,staff_id INTEGER,role TEXT NOT NULL,at INTEGER NOT NULL);
